package com.arxyt.territorycontrolcompat.network;
import com.arxyt.territorycontrolcompat.data.CompatSavedData; import net.minecraft.network.FriendlyByteBuf; import net.minecraftforge.api.distmarker.Dist; import net.minecraftforge.fml.DistExecutor; import net.minecraftforge.network.NetworkEvent; import java.util.function.Supplier;
public record CompatConfigPacket(CompatSavedData.Config config,boolean open){public void encode(FriendlyByteBuf b){b.writeBoolean(config.balancedOvaryDensity());b.writeBoolean(config.restrictCaerula());b.writeBoolean(config.tideRecession());b.writeBoolean(config.restrictEyes());b.writeBoolean(config.eyesCollapse());b.writeBoolean(config.restrictPhayriosis());b.writeBoolean(config.phayriosisCure());b.writeBoolean(open);}public static CompatConfigPacket decode(FriendlyByteBuf b){return new CompatConfigPacket(new CompatSavedData.Config(b.readBoolean(),b.readBoolean(),b.readBoolean(),b.readBoolean(),b.readBoolean(),b.readBoolean(),b.readBoolean()),b.readBoolean());}public static void handle(CompatConfigPacket p,Supplier<NetworkEvent.Context> s){s.get().enqueueWork(()->DistExecutor.unsafeRunWhenOn(Dist.CLIENT,()->()->com.arxyt.territorycontrolcompat.client.CompatClientEvents.receiveConfig(p.config(),p.open())));s.get().setPacketHandled(true);}}
